style.css:
@-moz-document domain("chat.openai.com") {
body {
    background-image: url("https://i.imgur.com/QElwrNc.png");
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
    background-attachment: fixed;
  }

  /* Fondo blanco semi-transparente para que el texto se lea mejor */
  .flex.h-full.w-full.flex-col {
    background-color: rgba(255, 255, 255, 0.75);
  }

  /* Opcional: bordes redondeados a las ventanas */
  .text-token-text-primary {
    border-radius: 10px;
  }

  /* Elimina sombras oscuras */
  .dark {
    box-shadow: none;
  }
}
